package com.agriconnect.rescue;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;@Component class InternalApiKeyFilter extends OncePerRequestFilter{private final byte[]key;InternalApiKeyFilter(@Value("${internal.api-key}")String k){key=k.getBytes(StandardCharsets.UTF_8);}protected boolean shouldNotFilter(HttpServletRequest r){return!r.getRequestURI().startsWith("/internal/");}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String value=r.getHeader("X-Internal-Api-Key");if(value==null||!MessageDigest.isEqual(key,value.getBytes(StandardCharsets.UTF_8))){p.sendError(403,"Invalid internal API key");return;}c.doFilter(r,p);}}
